let replayRecords=[],activeReplay=null,copyNoticeTimer=null,copyOperation=0;
try{const saved=JSON.parse(localStorage.getItem('bj-lab-replays-v1'));if(Array.isArray(saved))replayRecords=saved.filter(r=>r&&r.schema===1&&Array.isArray(r.decisions)).slice(-20)}catch{}
const replayText=(zh,en)=>language==='zh'?zh:en;
function cloneCards(cards){return cards.map(c=>({r:c.r,s:c.s,v:c.v}))}
function replayHands(){return hands.map((h,i)=>({index:i,cards:cloneCards(h.cards),...value(h.cards),betUnits:h.bet,splitAceLocked:!!h.locked,result:h.result||null}))}
function replayState(){return {activeHandIndex:idx,hands:replayHands(),dealerUpcard:cloneCards(dealer.slice(0,1))[0],done,answered}}
function saveReplays(){try{localStorage.setItem('bj-lab-replays-v1',JSON.stringify(replayRecords))}catch{}}
function beginReplay(){for(const r of replayRecords)if(r.status==='in-progress'){r.status='interrupted';r.endedAt=new Date().toISOString()}activeReplay={schema:1,id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),mode,reviewing,status:'in-progress',startedAt:new Date().toISOString(),rules:{decks:6,shuffle:'Every new round',dealerSoft17:'stand',holeCard:'US peek before player actions',blackjackPayout:'3:2',double:'Any first two cards, including after split',split:'Equal value, max 4 hands; split aces get one card each and cannot resplit',surrender:false,insurance:false,split21:'Regular 21, not a natural blackjack',training:'One decision per question, no round outcome'},initial:replayState(),decisions:[]};replayRecords.push(activeReplay);replayRecords=replayRecords.slice(-20);saveReplays()}
function startDecision(action,recommendation){const event={step:activeReplay.decisions.length+1,time:new Date().toISOString(),action,actionName:{H:'hit',S:'stand',D:'double',P:'split'}[action],before:replayState(),appRecommendation:{action:recommendation.a,reasonZh:recommendation.why},matchesAppStrategy:action===recommendation.a,guidanceVisible:mode==='learn'};activeReplay.decisions.push(event);saveReplays();return event}
function endDecision(event){event.after=replayState();saveReplays()}
function completeReplay(result){if(!activeReplay||activeReplay.status!=='in-progress')return;Object.assign(activeReplay,{status:'completed',endedAt:new Date().toISOString(),result});saveReplays()}
function compactCards(cards){return (cards||[]).map(c=>c.r==='10'?'T':c.r).join('')||'-'}
function compactHands(hs){return hs.map(h=>'h'+h.index+'='+compactCards(h.cards)+'/'+h.total+(h.soft?'s':'h')+' x'+h.betUnits+(h.splitAceLocked?' locked':'')).join(';')}
function exportReplays(){const lines=[replayText('请按顺序复盘我的 Blackjack 决策，独立核对基础策略，说明替代操作与理由。按当时庄家明牌判断，区分事后暗牌和抽牌结果，不用输赢倒推决策好坏。可交给 Codex、Claude 等工具分析。','Review my blackjack decisions in order. Independently check basic strategy and explain alternatives. Judge by the dealer upcard at the time, not later hole cards, draws or outcomes. For Codex, Claude or similar tools.'),'Blackjack compact v2',replayText('记号：T=10，A=Ace；H=要牌 S=停牌 D=加倍 P=分牌；h0等为当时手牌编号，/点数+s/h=软/硬，x=注额，locked=分A锁定。coach=应用建议（非标准答案），guided=当时可见提示。初始只有庄家明牌，完成后 dealer 才显示完整牌。','Notation: T=10, A=ace; H=hit S=stand D=double P=split. h0 etc are hand indexes at that step; /total+s/h=soft/hard; x=stake; locked=split ace. coach=app suggestion, not ground truth; guided=hint visible. Initial dealer is upcard only; full dealer cards appear only in completed outcomes.')];const ruleIds=new Map();for(const [i,r]of replayRecords.entries()){const rule=JSON.stringify(r.rules);lines.push('','#'+(i+1)+' '+r.mode+' '+r.status+' '+r.startedAt.slice(0,19)+(r.reviewing?' review':''));if(!ruleIds.has(rule)){ruleIds.set(rule,ruleIds.size+1);lines.push('Rules'+ruleIds.get(rule)+' '+rule)}lines.push('rules='+ruleIds.get(rule)+' dealerUp='+compactCards([r.initial.dealerUpcard])+' '+compactHands(r.initial.hands));for(const d of r.decisions){const h=d.before.hands[d.before.activeHandIndex];let line=d.step+' h'+d.before.activeHandIndex+' '+compactCards(h.cards)+' '+d.action+' coach='+d.appRecommendation.action+(d.guidanceVisible?' guided':'');if(d.after)line+=' => '+compactHands(d.after.hands);lines.push(line)}if(r.result){if(r.mode==='train')lines.push('correct='+r.result.correct);else lines.push('result net='+r.result.netUnits+' dealer='+compactCards(r.result.dealer)+'/'+r.result.dealerTotal+' '+compactHands(r.result.hands))}if(r.id===activeReplay?.id&&r.status==='in-progress')lines.push('now h'+idx+' '+compactHands(replayHands()))}return lines.join('\n')}
function manualCopyHelp(){return replayText('文本已选中，可按 Ctrl/Cmd+C 复制，再发给 Codex、Claude 等工具。保留最近 20 局／题。','Text selected. Press Ctrl/Cmd+C, then send it to Codex, Claude or a similar tool. Includes up to 20 rounds/questions.')}
function showReplayText(text){$('export-text').value=text;$('export-modal').hidden=false;$('export-help').textContent=manualCopyHelp();$('export-text').focus();$('export-text').select()}
async function copyReplay(text){const operation=++copyOperation;if(copyNoticeTimer)clearTimeout(copyNoticeTimer);$('export-status').textContent='';try{if(!navigator.clipboard?.writeText)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(text);if(operation!==copyOperation)return;$('export-status').textContent=replayText('✓ 已复制，可粘贴给 Codex、Claude 等工具分析。','✓ Copied. Paste into Codex, Claude or a similar tool.');if(!$('export-modal').hidden)$('export-help').textContent=replayText('✓ 已复制到剪贴板。','✓ Copied to clipboard.');copyNoticeTimer=setTimeout(()=>{$('export-status').textContent='';if(!$('export-modal').hidden)$('export-help').textContent=manualCopyHelp();copyNoticeTimer=null},2000)}catch{if(operation!==copyOperation)return;showReplayText(text);$('export-status').textContent=replayText('浏览器不允许自动复制，请在弹窗中手动复制。','Automatic copy is unavailable. Copy the text from the dialog.')}}
function initReplayUI(){$('export').onclick=()=>copyReplay(exportReplays());$('export-copy').onclick=()=>copyReplay($('export-text').value);const close=()=>{$('export-modal').hidden=true;$('export').focus()};$('export-close').onclick=close;$('export-modal').onclick=e=>{if(e.target===$('export-modal'))close()};$('export-modal').onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();close()}else if(e.key==='Tab'){if(e.shiftKey&&document.activeElement===$('export-close')){e.preventDefault();$('export-copy').focus()}else if(!e.shiftKey&&document.activeElement===$('export-copy')){e.preventDefault();$('export-close').focus()}}}}
